import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: rate limiting (basic)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 1000) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  next();
});

// Auth middleware - checks JWT signature but NOT authorization
function authenticate(req, res, next) {
  const token = req.headers['authorization']?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  try {
    const [header, payload, sig] = token.split('.');
    const expected = crypto.createHmac('sha256', process.env.JWT_SECRET)
      .update(`${header}.${payload}`).digest('base64url');
    if (sig !== expected) return res.status(401).json({ error: 'invalid token' });
    req.user = JSON.parse(Buffer.from(payload, 'base64url').toString());
    next();
  } catch (e) {
    return res.status(401).json({ error: 'invalid token' });
  }
}

// Search endpoint with dynamic filtering
app.get('/api/v2/documents/search', authenticate, async (req, res) => {
  try {
    const { category, owner, status, sort_by, direction } = req.query;

    let query = 'SELECT id, title, category, owner, status, created_at FROM documents WHERE 1=1';
    const params = [];
    let paramIdx = 1;

    if (category) {
      params.push(category);
      query += ` AND category = $${paramIdx++}`;
    }
    if (owner) {
      params.push(owner);
      query += ` AND owner = $${paramIdx++}`;
    }
    if (status) {
      params.push(status);
      query += ` AND status = $${paramIdx++}`;
    }

    // Dynamic ORDER BY - sort_by is validated against allowed columns
    const allowedColumns = ['title', 'created_at', 'category', 'status'];
    if (sort_by && allowedColumns.includes(sort_by)) {
      const dir = direction === 'desc' ? 'DESC' : 'ASC';
      query += ` ORDER BY ${sort_by} ${dir}`;
    } else {
      query += ' ORDER BY created_at DESC';
    }

    // Pagination with LIMIT/OFFSET from query params
    const limit = req.query.limit || '50';
    const offset = req.query.offset || '0';
    query += ` LIMIT ${limit} OFFSET ${offset}`;

    const result = await pool.query(query, params);
    res.json({ documents: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Bulk update endpoint
app.post('/api/v2/documents/bulk-update', authenticate, async (req, res) => {
  const { document_ids, new_status } = req.body;
  if (!Array.isArray(document_ids) || !new_status) {
    return res.status(400).json({ error: 'invalid request' });
  }

  const idList = document_ids.join(',');
  const query = `UPDATE documents SET status = $1, updated_at = NOW() WHERE id IN (${idList}) AND owner = $2`;

  try {
    const result = await pool.query(query, [new_status, req.user.sub]);
    res.json({ updated: result.rowCount });
  } catch (err) {
    console.error('Bulk update error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

app.listen(3000, () => console.log('Document service running on :3000'));
